import os
import time
from typing import List, Optional, Dict, Any, Tuple
from pathlib import Path
import logging

from SSI_V5.ingestion.result_models import MatchResult, ImportStatistics
from SSI_V5.ingestion.result_parser import ResultParser, ParseError


# Konfiguracja logowania
logger = logging.getLogger(__name__)


class ImportError(Exception):
    """Wyjatek dla bledow importu"""
    pass


class ImportWarning:
    """Klasa dla ostrzezen importu"""
    def __init__(self, message: str, line_number: int = 0, severity: str = "warning"):
        self.message = message
        self.line_number = line_number
        self.severity = severity
    
    def __str__(self) -> str:
        return f"[{self.severity.upper()}] Line {self.line_number}: {self.message}"


class ResultImporter:
    """
    Importer wynikow meczow z plikow CSV.
    
    Odpowiedzialny za:
    - Ladowanie pliku z dysku
    - Walidacje kodowania
    - Transformacje do obiektow MatchResult
    - Zarzadzanie statystykami importu
    """
    
    def __init__(self, parser: Optional[ResultParser] = None):
        """
        Inicjalizacja importera.
        
        Args:
            parser: Instancja ResultParser (opcjonalnie)
        """
        self.parser = parser or ResultParser()
        self.warnings: List[ImportWarning] = []
        self.errors: List[str] = []
        self.stats: ImportStatistics = ImportStatistics()
        self._large_file_threshold = 10 * 1024 * 1024  # 10MB
    
    def load_csv(self, file_path: str, encoding: Optional[str] = None) -> Tuple[List[MatchResult], ImportStatistics]:
        """
        Laduje plik CSV i konwertuje do listy MatchResult.
        
        Args:
            file_path: Sciezka do pliku CSV
            encoding: Kodowanie (opcjonalnie, domyslnie auto-detekcja)
            
        Returns:
            Tuple: (lista MatchResult, statystyki importu)
            
        Raises:
            ImportError: Jesli plik nie istnieje lub ma zly format
        """
        start_time = time.time()
        
        # Resetujemy statystyki
        self.warnings = []
        self.errors = []
        self.stats = ImportStatistics()
        
        # Walidacja sciezki
        if not os.path.exists(file_path):
            raise ImportError(f"File not found: {file_path}")
        
        if not os.path.isfile(file_path):
            raise ImportError(f"Not a file: {file_path}")
        
        # Sprawdzam rozmiar pliku
        file_size = os.path.getsize(file_path)
        if file_size == 0:
            logger.warning(f"Empty file: {file_path}")
            return [], self.stats
        
        if file_size > self._large_file_threshold:
            logger.info(f"Processing large file: {file_path} ({file_size / (1024*1024):.2f} MB)")
        
        # Wczytywanie pliku
        try:
            content = self._read_file(file_path, encoding)
        except Exception as e:
            raise ImportError(f"Failed to read file {file_path}: {str(e)}")
        
        # Parsowanie zawartosci
        try:
            results, parse_stats = self.parser.parse_csv_content(content)
        except Exception as e:
            raise ImportError(f"Failed to parse CSV content: {str(e)}")
        
        # Aktualizujemy statystyki
        self.stats.loaded = parse_stats.loaded
        self.stats.errors = parse_stats.errors
        self.stats.skipped = parse_stats.skipped
        self.stats.processing_time = time.time() - start_time
        
        # Logujemy statystyki
        logger.info(f"Import completed: {self.stats}")
        
        return results, self.stats
    
    def load_csv_string(self, csv_content: str) -> Tuple[List[MatchResult], ImportStatistics]:
        """
        Laduje zawartosc CSV z stringa.
        
        Args:
            csv_content: Zawartosc CSV jako string
            
        Returns:
            Tuple: (lista MatchResult, statystyki)
        """
        start_time = time.time()
        
        self.warnings = []
        self.errors = []
        self.stats = ImportStatistics()
        
        try:
            results, parse_stats = self.parser.parse_csv_content(csv_content)
        except Exception as e:
            raise ImportError(f"Failed to parse CSV content: {str(e)}")
        
        self.stats.loaded = parse_stats.loaded
        self.stats.errors = parse_stats.errors
        self.stats.skipped = parse_stats.skipped
        self.stats.processing_time = time.time() - start_time
        
        return results, self.stats
    
    def load_multiple_files(self, file_paths: List[str]) -> Tuple[List[MatchResult], Dict[str, ImportStatistics]]:
        """
        Laduje wiele plikow CSV.
        
        Args:
            file_paths: Lista sciezek do plikow
            
        Returns:
            Tuple: (laczna lista MatchResult, slownik statystyk per plik)
        """
        all_results: List[MatchResult] = []
        file_stats: Dict[str, ImportStatistics] = {}
        all_errors: List[str] = []
        
        for file_path in file_paths:
            try:
                results, stats = self.load_csv(file_path)
                all_results.extend(results)
                file_stats[file_path] = stats
            except ImportError as e:
                error_msg = f"Failed to import {file_path}: {str(e)}"
                all_errors.append(error_msg)
                logger.error(error_msg)
                
                # Tworzymy puste statystyki dla nieudanych plikow
                file_stats[file_path] = ImportStatistics(errors=1)
        
        # Laczna statystyka
        total_stats = ImportStatistics()
        for stats in file_stats.values():
            total_stats.loaded += stats.loaded
            total_stats.errors += stats.errors
            total_stats.skipped += stats.skipped
            total_stats.duplicates += stats.duplicates
        
        if all_errors:
            self.errors = all_errors
        
        return all_results, file_stats
    
    def _read_file(self, file_path: str, encoding: Optional[str] = None) -> str:
        """
        Wczytuje plik z dysku.
        
        Args:
            file_path: Sciezka do pliku
            encoding: Kodowanie (opcjonalnie)
            
        Returns:
            Zawartosc pliku jako string
            
        Raises:
            ImportError: Jesli nie mozna odczytac pliku
        """
        # Auto-detekcja kodowania jesli nie podano
        if encoding is None:
            encoding = self._detect_encoding(file_path)
            logger.info(f"Detected encoding: {encoding} for {file_path}")
        
        # Wczytywanie z odpowiednim kodowaniem
        try:
            with open(file_path, 'r', encoding=encoding, errors='replace') as f:
                content = f.read()
        except UnicodeDecodeError as e:
            # Jesli auto-detekcja sie nie powiodla, próbujemy UTF-8 z ignorowaniem bledow
            logger.warning(f"Failed to decode with {encoding}, trying UTF-8 with errors='replace'")
            with open(file_path, 'rb') as f:
                content = f.read().decode('utf-8', errors='replace')
        except Exception as e:
            raise ImportError(f"Cannot read file {file_path}: {str(e)}")
        
        # Walidacja UTF-8
        try:
            content.encode('utf-8')
        except UnicodeEncodeError:
            # Próbujemy naprawic kodowanie
            content = self._fix_encoding(content)
        
        return content
    
    def _detect_encoding(self, file_path: str) -> str:
        """Detekuje kodowanie pliku - uproszczona wersja bez chardet"""
        # Domyslnie uzywa UTF-8
        return 'utf-8'
    
    def _fix_encoding(self, content: str) -> str:
        """Próbuje naprawic problemy z kodowaniem"""
        # Usuwamy niepoprawne znaki
        return content.encode('utf-8', errors='ignore').decode('utf-8', errors='replace')
    
    def validate_file(self, file_path: str) -> Dict[str, Any]:
        """
        Waliduje plik CSV przed importem.
        
        Args:
            file_path: Sciezka do pliku
            
        Returns:
            Slownik z wynikami walidacji
        """
        validation = {
            'valid': True,
            'file_exists': False,
            'is_file': False,
            'encoding_valid': False,
            'has_content': False,
            'errors': []
        }
        
        # Sprawdzamy czy plik istnieje
        if not os.path.exists(file_path):
            validation['valid'] = False
            validation['errors'].append(f"File not found: {file_path}")
            return validation
        
        validation['file_exists'] = True
        
        # Sprawdzamy czy to plik
        if not os.path.isfile(file_path):
            validation['valid'] = False
            validation['errors'].append(f"Not a file: {file_path}")
            return validation
        
        validation['is_file'] = True
        
        # Sprawdzamy rozmiar
        file_size = os.path.getsize(file_path)
        if file_size == 0:
            validation['valid'] = False
            validation['errors'].append("Empty file")
            return validation
        
        validation['has_content'] = True
        
        # Sprawdzamy kodowanie
        try:
            encoding = self._detect_encoding(file_path)
            with open(file_path, 'r', encoding=encoding) as f:
                f.read(1024)  # Próbujemy przeczytac pierwszy kilobajt
            validation['encoding_valid'] = True
        except Exception as e:
            validation['valid'] = False
            validation['errors'].append(f"Encoding error: {str(e)}")
        
        return validation
    
    def get_batch_importer(self, batch_size: int = 1000):
        """
        Zwraca generator dla duzych plikow (przetwarzanie w batchach).
        
        Args:
            batch_size: Rozmiar batcha
            
        Returns:
            Generator zwracajacy batch MatchResult
        """
        def batch_generator(file_path: str):
            """Generator batchy"""
            # Tutaj bym zaimplementowal czytanie pliku w batchach
            # Na razie zwracamy pusty generator
            yield []
        
        return batch_generator
    
    def get_errors(self) -> List[str]:
        """Zwraca liste bledow"""
        return self.errors.copy()
    
    def get_warnings(self) -> List[ImportWarning]:
        """Zwraca liste ostrzezen"""
        return self.warnings.copy()
    
    def get_statistics(self) -> ImportStatistics:
        """Zwraca statystyki importu"""
        return self.stats
    
    def reset(self):
        """Resetuje stan importera"""
        self.warnings = []
        self.errors = []
        self.stats = ImportStatistics()
        self.parser.reset()


# Funkcje pomoca (module-level)

def import_results(file_path: str) -> Tuple[List[MatchResult], ImportStatistics]:
    """
    Funkcja wygodna do importu wynikow.
    
    Args:
        file_path: Sciezka do pliku CSV
        
    Returns:
        Tuple: (lista MatchResult, statystyki)
    """
    importer = ResultImporter()
    return importer.load_csv(file_path)


def import_results_string(csv_content: str) -> Tuple[List[MatchResult], ImportStatistics]:
    """
    Funkcja wygodna do importu z stringa.
    
    Args:
        csv_content: Zawartosc CSV
        
    Returns:
        Tuple: (lista MatchResult, statystyki)
    """
    importer = ResultImporter()
    return importer.load_csv_string(csv_content)
